CREATE DATABASE IF NOT EXISTS wolt_project CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE wolt_project;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('customer','admin') DEFAULT 'customer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE restaurants (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(130) NOT NULL,cuisine VARCHAR(80),description TEXT,area VARCHAR(80),image_url TEXT,rating DECIMAL(2,1) DEFAULT 4.7,delivery_minutes SMALLINT DEFAULT 25,delivery_fee DECIMAL(6,2) DEFAULT 1.49,is_active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE food_items (id INT AUTO_INCREMENT PRIMARY KEY,restaurant_id INT NOT NULL,name VARCHAR(130) NOT NULL,description TEXT,price DECIMAL(8,2) NOT NULL,image_url TEXT,is_available BOOLEAN DEFAULT TRUE,FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE CASCADE);
CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,restaurant_id INT NULL,delivery_address VARCHAR(255),total DECIMAL(10,2) NOT NULL,status ENUM('pending','confirmed','preparing','on_the_way','delivered','cancelled') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY (restaurant_id) REFERENCES restaurants(id) ON DELETE SET NULL);
CREATE TABLE order_items (id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,food_item_id INT NULL,name_snapshot VARCHAR(130) NOT NULL,price DECIMAL(8,2) NOT NULL,quantity SMALLINT NOT NULL,FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY (food_item_id) REFERENCES food_items(id) ON DELETE SET NULL);
